contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amount, uint withdrawValue, bool tryNonOwnerWithdrawAll) public payable {
        require(address(this).balance >= amount);

        // Fund the contract under test through its receive() to establish a nonzero balance.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        uint beforeOwnerBalance = c.owner().balance;

        bool nonOwnerReverted;
        if (tryNonOwnerWithdrawAll) {
            try c.withdrawAll() { nonOwnerReverted = false; } catch { nonOwnerReverted = true; }
        } else {
            nonOwnerReverted = true;
        }

        // The owner must be able to withdraw the entire balance, and doing so must leave
        // the contract with zero balance while preserving depositsCount (withdraw doesn't touch it).
        c.withdrawAll();

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        assert(
            beforeBalance > 0 &&
            nonOwnerReverted &&
            afterBalance == 0 &&
            afterDeposits == beforeDeposits &&
            address(c).balance == 0
        );
    }

    receive() external payable {}
}

