contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint depositAmount, uint withdrawalAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");
        require(address(this).balance >= withdrawalAmount, "insufficient test balance");

        // deposit so the contract has some balance to attempt to withdraw
        (bool okDeposit, ) = address(c).call{value: depositAmount}("");
        require(okDeposit, "deposit failed");

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        bool reverted;
        if (caller == address(this)) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
            reverted = !ok;
        }

        assert(
            (caller == address(this) && !reverted ? address(c).balance == 0 : true) &&
            (caller != address(this) ? (reverted && address(c).balance == balBefore + withdrawalAmount || address(c).balance == balBefore) && c.depositsCount() == depositsBefore : true)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance for deposit");
        require(depositAmount > 0, "deposit must be positive");
        require(withdrawAmount > 0, "withdraw must be positive");

        // deposit Ether into c to fund the withdrawal
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        uint balBefore = address(c).balance;
        uint ownerBalBefore = address(this).balance;

        bool reverted;
        if (withdrawAmount <= balBefore) {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (withdrawAmount <= balBefore) {
            assert(!reverted && address(c).balance == balBefore - withdrawAmount && address(this).balance == ownerBalBefore + withdrawAmount);
        } else {
            assert(reverted && address(c).balance == balBefore && address(this).balance == ownerBalBefore);
        }
    }

    receive() external payable {}
}

