        bool reverted;
        uint callBalanceBefore = address(this).balance;
        c.sendMoney{value: value}(target, value, new bytes(0));
        uint callBalanceAfter = address(this).balance;
        reverted = (callBalanceAfter == callBalanceBefore);

        uint cAfter = address(c).balance;
        uint targetAfter = target.balance;

        assert(reverted == false ? (cAfter == cBefore - value && targetAfter == targetBefore + value) : (cAfter == cBefore && targetAfter == targetBefore));
    }
