contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "not enough balance");

        c.receive{value: amount}();
        uint balAfterDeposit = address(c).balance;
        require(balAfterDeposit >= amount, "deposit not reflected");
        uint depositsBefore = c.depositsCount();
        uint ownerBalBefore = address(this).balance;

        c.withdraw(amount);
        uint balAfterWithdraw = address(c).balance;
        uint depositsAfter = c.depositsCount();

        bool nonOwnerReverts = false;
        // The test contract is the owner, so a non-owner call is not possible directly here.
        // Instead we check the observable accounting invariant after the owner's withdraw.
        // The general rule: owner withdrawal reduces contract balance by exactly amount,
        // depositsCount is unchanged, and the amount was received back by the test contract.
        assert(
            balAfterWithdraw == balAfterDeposit - amount &&
            depositsAfter == depositsBefore &&
            address(this).balance == ownerBalBefore + amount &&
            !nonOwnerReverts
        );
    }

    receive() external payable {}
}

