        uint depositsBefore = c.depositsCount();
        uint ownerBalBefore = address(this).balance;

        // Deposit via the payable receive callback; send ETH along.
        (bool depositOk, ) = address(c).call{value: amount}("");
        require(depositOk, "deposit failed");

        uint balAfterDeposit = address(c).balance;
        uint depositsAfterDeposit = c.depositsCount();

